use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

/// The hosts this node's `HTTPClient` handle is scoped to. A request outside
/// this set would trap at the boundary, so such URLs are reported as failures
/// without ever being attempted.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercased host of an http(s) URL, or explain why it has none
/// we are willing to request.
fn host_of(url: &str) -> Result<String, &'static str> {
    let rest = if let Some(r) = strip_prefix_ci(url, "https://") {
        r
    } else if let Some(r) = strip_prefix_ci(url, "http://") {
        r
    } else {
        return Err("unsupported URL scheme");
    };

    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    if authority.is_empty() {
        return Err("URL has no host");
    }
    if authority
        .chars()
        .any(|c| c == '@' || c == '\\' || c == '[' || c == ']' || c == '%' || c.is_whitespace() || c.is_control())
    {
        return Err("URL authority is not a plain host");
    }

    let host = match authority.rfind(':') {
        Some(i) => {
            let port = &authority[i + 1..];
            if !port.chars().all(|c| c.is_ascii_digit()) {
                return Err("URL has a malformed port");
            }
            &authority[..i]
        }
        None => authority,
    };

    if host.is_empty() {
        return Err("URL has no host");
    }
    Ok(host.to_ascii_lowercase())
}

fn strip_prefix_ci<'a>(s: &'a str, prefix: &str) -> Option<&'a str> {
    if s.len() >= prefix.len()
        && s.is_char_boundary(prefix.len())
        && s[..prefix.len()].eq_ignore_ascii_case(prefix)
    {
        Some(&s[prefix.len()..])
    } else {
        None
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received on this call, one URL per line.
        state_rw::put("last-input", &subscriptions.urls.join("\n"));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for raw in subscriptions.urls {
            let url = raw.trim();

            match host_of(url) {
                Ok(host) => {
                    if !ALLOWED_HOSTS.iter().any(|h| *h == host) {
                        failures.push(FetchFailure {
                            url: raw.clone(),
                            error: String::from("host is not in this node's allowlist"),
                        });
                        continue;
                    }
                }
                Err(reason) => {
                    failures.push(FetchFailure {
                        url: raw.clone(),
                        error: String::from(reason),
                    });
                    continue;
                }
            }

            match http_client::fetch(url) {
                Ok(body) => documents.push(FeedDocument {
                    url: raw.clone(),
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: raw.clone(),
                    error,
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
